   const r=await sendPost('/api/integrations/paystack/configure',paystackCredentials);
   const status=await api.get('/api/integrations/payments/status');
   setPaymentSettings(status.data);
   setPaystackCredentials(old=>({...old,secretKey:'',callbackHost:status.data.callbackHost||old.callbackHost,webhookHostRegistered:!!status.data.webhookHostRegistered}));
