 const visible=navItems.filter(([label,key])=>key==='notifications'?!!user:['promotions','reviews'].includes(key)?user.role==='Managing Director':key==='transactions'?allowed('sales'):key==='approvals'?user.role==='Managing Director':allowed(key)||key==='overview');
 const listPage=!!pageKey;
